-- Reimporta agosto, setiembre y octubre 2026 exclusivamente desde la hoja BD CJS716 del Excel de cierre.
-- Los cierres APROBADOS permanecen inmutables; solo se reemplazan borradores y se crean liquidaciones donde no hay cierre aprobado.
-- 145 filas (37/52/56), km 4,293/3,981/4,148.90. Octubre incluye los viajes del 1 al 10 omitidos en la carga parcial.
BEGIN;

ALTER TABLE public.lease_usage_records ALTER COLUMN km DROP NOT NULL;

DO $$
DECLARE
  v_vehicle uuid;
  v_contract uuid;
  v_period record;
  v_settlement uuid;
  v_decision jsonb;
  v_count integer;
  v_km numeric;
  v_missing integer;
  v_km_gps numeric;
  v_km_fuera numeric;
  v_detail jsonb;
  v_days integer;
  v_labor_days integer;
  v_base numeric := 3676.92;
  v_included numeric := 3900;
  v_rate numeric := 1.9428;
  v_excess numeric;
  v_excess_amount numeric;
  v_subtotal numeric;
  v_tax numeric;
BEGIN
  SELECT id INTO v_vehicle FROM public.vehicles
  WHERE public.fe_code(plate) = 'CJS 716' ORDER BY id LIMIT 1;
  IF v_vehicle IS NULL THEN
    RAISE NOTICE 'Se omite la valorización histórica de CJS716: la unidad no está registrada en este entorno';
    RETURN;
  END IF;

  SELECT id INTO v_contract FROM public.vehicle_lease_contracts
  WHERE vehicle_id = v_vehicle AND status = 'ACTIVO'
    AND start_date <= DATE '2026-10-31' AND COALESCE(end_date, DATE 'infinity') >= DATE '2026-08-01'
  ORDER BY start_date DESC LIMIT 1;
  IF v_contract IS NULL THEN RAISE EXCEPTION 'No se encontró contrato activo de CJS716 para agosto-octubre'; END IF;

  -- No reemplazar una liquidación aprobada; requiere reversa autorizada previa.
  FOR v_period IN
    SELECT id, period_start, status FROM public.lease_settlements
    WHERE contract_id = v_contract AND period_start IN (DATE '2026-08-01', DATE '2026-09-01', DATE '2026-10-01')
      AND status <> 'ANULADA' ORDER BY period_start
  LOOP
    IF v_period.status = 'BORRADOR' THEN
      v_decision := public.decide_lease_settlement(v_period.id, 'ANULADA',
        'Reemplazada por la recarga de la hoja BD CJS716 del Excel de cierre 2026.');
      IF NOT COALESCE((v_decision ->> 'success')::boolean, false) THEN
        RAISE EXCEPTION 'No se pudo anular el borrador de %: %', v_period.period_start, v_decision ->> 'error';
      END IF;
    ELSIF v_period.status <> 'APROBADA' THEN
      RAISE EXCEPTION 'Estado de liquidación inesperado para %: %', v_period.period_start, v_period.status;
    END IF;
  END LOOP;

  -- Reemplazar únicamente las valorizaciones de Excel de estos tres meses; mantener GPS y datos de rutas.
  DELETE FROM public.lease_usage_records
  WHERE vehicle_id = v_vehicle AND fecha >= DATE '2026-08-01' AND fecha < DATE '2026-11-01'
    AND fuente IN ('VALORIZACION_EXCEL', 'VALORIZACION_EXCEL_CIERRE_OCT_2026', 'VALORIZACION_EXCEL_CIERRE_2026');

  INSERT INTO public.lease_usage_records
    (vehicle_id, fecha, fuente, tipo_operacion, guia, ot_oc, area, conductor, licencia,
     cliente, zona, destino, km, km_entrega, propiedad, observaciones)
  SELECT v_vehicle, x.fecha, 'VALORIZACION_EXCEL_CIERRE_2026', x.tipo, x.guia, x.ot_oc,
         x.area, x.conductor, x.licencia, x.cliente, x.zona, x.destino, x.km, x.km_entrega::numeric,
         x.propiedad, x.observaciones
  FROM (VALUES
      (DATE '2026-08-03', 'DESPACHO DE CONTRATOS', 'T001-00006327', '0000016308', 'CONTRATOS', 'ALVARO CAYTUIRO TAPIA', 'Q43501327', 'MOLITALIA S.A', 'ZONA NORTE', 'Los Olivos', 266, 133, 'TERCERO', NULL),
      (DATE '2026-08-04', 'DESPACHO DE CONTRATOS', 'T001-00006342', '0000016071', 'CONTRATOS', 'ALVARO CAYTUIRO TAPIA', 'Q43501327', 'REFINERIA LA PAMPILLA S.A.', 'ZONA NORTE', 'Ventanilla', 64, 32, 'TERCERO', NULL),
      (DATE '2026-08-04', 'DESPACHO DE CONTRATOS', 'T001-00006341', '0000016392', 'CONTRATOS', 'ALVARO CAYTUIRO TAPIA', 'Q43501327', 'HOMECENTERS PERUANOS S.A.', 'ZONA CENTRO', 'San Miguel', 64, 32, 'TERCERO', NULL),
      (DATE '2026-08-05', 'DESPACHO DE CONTRATOS', 'T001-00006350', '0000016060', 'CONTRATOS', 'ALVARO CAYTUIRO TAPIA', 'Q43501327', 'SOFTYS PERU S.A.C.', 'ZONA SUR', 'Punta Hermosa', 156, 78, 'TERCERO', NULL),
      (DATE '2026-08-05', 'DESPACHO DE CONTRATOS', 'T001-00006349', '0000016405', 'CONTRATOS', 'ALVARO CAYTUIRO TAPIA', 'Q43501327', 'CORE TECH S.A', 'ZONA SUR', 'Chorrillos', 156, 78, 'TERCERO', NULL),
