      (DATE '2026-10-30', 'DESPACHO DE CONTRATOS', 'T003-5576', '16101', 'Contratos', 'CAYTUIRO  TAPIA ALVARO', 'Q43501327', 'METALPREN S A', NULL, 'CERCADO DE LIMA', 227.24, NULL, 'TERCERO', NULL),
      (DATE '2026-10-30', 'RECOJO DE ORDENES DE COMPRA', 'T002-4164', 'OSSRE0001', 'Compras', 'CAYTUIRO  TAPIA ALVARO', 'Q43501327', NULL, NULL, 'COMAS', NULL, NULL, 'TERCERO', NULL),
      (DATE '2026-10-30', 'RECOJO DE ORDENES DE COMPRA', 'T001-4257', 'OC58030', 'Compras', 'CAYTUIRO  TAPIA ALVARO', 'Q43501327', NULL, NULL, 'CHILCA', NULL, NULL, 'TERCERO', NULL),
      (DATE '2026-10-31', 'DESPACHO DE CONTRATOS', 'T001-6867', '16534', 'Contratos', 'CAYTUIRO  TAPIA ALVARO', 'Q43501327', 'SOCIEDAD AGRICOLA DROKASA S.A.', NULL, 'LA VICTORIA', 178.79, NULL, 'TERCERO', NULL)
  ) AS x(fecha, tipo, guia, ot_oc, area, conductor, licencia, cliente, zona, destino, km, km_entrega, propiedad, observaciones);

  -- Valida conteo y kilometraje contra el Excel por mes.
  IF (SELECT count(*) FROM public.lease_usage_records WHERE vehicle_id=v_vehicle AND fecha >= DATE '2026-08-01' AND fecha < DATE '2026-09-01' AND fuente='VALORIZACION_EXCEL_CIERRE_2026') <> 37
     OR (SELECT COALESCE(sum(km),0) FROM public.lease_usage_records WHERE vehicle_id=v_vehicle AND fecha >= DATE '2026-08-01' AND fecha < DATE '2026-09-01' AND fuente='VALORIZACION_EXCEL_CIERRE_2026') <> 4293
     OR (SELECT count(*) FROM public.lease_usage_records WHERE vehicle_id=v_vehicle AND fecha >= DATE '2026-09-01' AND fecha < DATE '2026-10-01' AND fuente='VALORIZACION_EXCEL_CIERRE_2026') <> 52
     OR (SELECT COALESCE(sum(km),0) FROM public.lease_usage_records WHERE vehicle_id=v_vehicle AND fecha >= DATE '2026-09-01' AND fecha < DATE '2026-10-01' AND fuente='VALORIZACION_EXCEL_CIERRE_2026') <> 3981
     OR (SELECT count(*) FROM public.lease_usage_records WHERE vehicle_id=v_vehicle AND fecha >= DATE '2026-10-01' AND fecha < DATE '2026-11-01' AND fuente='VALORIZACION_EXCEL_CIERRE_2026') <> 56
     OR (SELECT COALESCE(sum(km),0) FROM public.lease_usage_records WHERE vehicle_id=v_vehicle AND fecha >= DATE '2026-10-01' AND fecha < DATE '2026-11-01' AND fuente='VALORIZACION_EXCEL_CIERRE_2026') <> 4148.90
     OR (SELECT count(*) FROM public.lease_usage_records WHERE vehicle_id=v_vehicle AND fecha >= DATE '2026-10-01' AND fecha < DATE '2026-11-01' AND fuente='VALORIZACION_EXCEL_CIERRE_2026' AND km IS NULL) <> 17 THEN
    RAISE EXCEPTION 'Validación Excel CJS716 no coincide: agosto 37/4293, setiembre 52/3981, octubre 56/4148.90 con 17 km vacíos';
  END IF;

  FOR v_period IN SELECT * FROM (VALUES
    (DATE '2026-08-01', DATE '2026-08-31', 31, 26),
    (DATE '2026-09-01', DATE '2026-09-30', 30, 26),
    (DATE '2026-10-01', DATE '2026-10-31', 31, 26)
  ) AS p(period_start, period_end, days, labor_days)
  LOOP
    -- No crear una segunda liquidación ni modificar la instantánea aprobada de ese mes.
    IF EXISTS (SELECT 1 FROM public.lease_settlements WHERE contract_id=v_contract AND period_start=v_period.period_start AND status='APROBADA') THEN
      CONTINUE;
    END IF;
    SELECT count(*), sum(km), count(*) FILTER (WHERE km IS NULL)
    INTO v_count, v_km, v_missing FROM public.lease_usage_records
    WHERE vehicle_id=v_vehicle AND fecha BETWEEN v_period.period_start AND v_period.period_end
      AND fuente='VALORIZACION_EXCEL_CIERRE_2026';
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'fecha', fecha, 'guia', guia, 'ref', COALESCE(guia, tipo_operacion), 'ot_oc', ot_oc,
      'area', area, 'cliente', cliente, 'zona', zona, 'destino', destino,
      'tipo', tipo_operacion, 'conductor', conductor, 'licencia', licencia,
      'km', km, 'km_entrega', km_entrega, 'propiedad', propiedad,
      'observaciones', observaciones, 'km_fuente', 'VALORIZACION_EXCEL_CIERRE_2026'
    ) ORDER BY fecha, guia NULLS LAST, ot_oc NULLS LAST), '[]'::jsonb)
    INTO v_detail FROM public.lease_usage_records
    WHERE vehicle_id=v_vehicle AND fecha BETWEEN v_period.period_start AND v_period.period_end
      AND fuente='VALORIZACION_EXCEL_CIERRE_2026';

    v_days := v_period.days;
    v_labor_days := v_period.labor_days;
    v_excess := GREATEST(v_km-v_included,0);
    v_excess_amount := round(v_excess*v_rate,2);
    SELECT sum(km) INTO v_km_gps FROM public.lease_gps_days
    WHERE vehicle_id=v_vehicle AND fecha BETWEEN v_period.period_start AND v_period.period_end;
    v_km_fuera := CASE WHEN v_km_gps IS NULL THEN NULL ELSE round(GREATEST(v_km_gps-v_km,0),2) END;
    v_subtotal := v_base+v_excess_amount;
    v_tax := round(v_subtotal*0.18,2);

    INSERT INTO public.lease_settlements
      (contract_id, vehicle_id, period_start, period_end, days, hours_used, km_used, downtime_days,
       base_amount, excess_km, excess_km_amount, excess_hours, excess_hours_amount, downtime_discount,
       other_discounts, penalties, consumptions, additional_costs, subtotal, tax, total, status, detail, notes)
    VALUES
